import{G as e,W as t,rt as n,t as r}from"./chunks/framework.3zKPIMIf.js";import"./chunks/assets.CQcr3VdQ.js";var i=JSON.parse(`{"title":"cBlock","description":"","frontmatter":{},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md"}`),a={name:`ja/index.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="cblock" tabindex="-1">cBlock <a class="header-anchor" href="#cblock" aria-label="Permalink to “cBlock”">​</a></h1><p>cBlockはあらゆるWebサイトで中国語・中国系のコンテンツを非表示にするブラウザ拡張機能です。</p><h2 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to “インストール”">​</a></h2><table tabindex="0"><thead><tr><th>Chrome</th><th>Firefox</th></tr></thead><tbody><tr><td><a href="https://chromewebstore.google.com/detail/oondbgdckgnijklignemhffjlkioodgp" target="_blank" rel="noreferrer"><img src="/images/chrome-web-store.png" alt="Chrome ウェブストアで入手" width="198" height="60"></a></td><td><a href="https://addons.mozilla.org/firefox/addon/cblock/" target="_blank" rel="noreferrer"><img src="/images/firefox-add-ons.png" alt="Firefox アドオンを入手" width="172" height="60"></a></td></tr></tbody></table><h2 id="必要な権限" tabindex="-1">必要な権限 <a class="header-anchor" href="#必要な権限" aria-label="Permalink to “必要な権限”">​</a></h2><table tabindex="0"><thead><tr><th>権限</th><th>用途</th></tr></thead><tbody><tr><td><code>storage</code></td><td>cBlockの設定とWebサイトへの問い合わせの結果を保存します</td></tr><tr><td><code>activeTab</code></td><td>ポップアップが現在のタブとそのWebサイトを調べられるようにします</td></tr><tr><td><code>declarativeNetRequest</code></td><td>中国系Webサイトへのアクセスをブロックします</td></tr><tr><td><code>http://*/*</code>、<code>https://*/*</code></td><td>すべてのWebサイトで中国語・中国系のコンテンツを見つけて非表示にします</td></tr></tbody></table><h2 id="cblockのしくみ" tabindex="-1">cBlockのしくみ <a class="header-anchor" href="#cblockのしくみ" aria-label="Permalink to “cBlockのしくみ”">​</a></h2><p>次の4つのしくみで中国語・中国系のコンテンツを非表示にし、<a href="#非表示にするもの">中国系Webサイト</a>への接続をブロックします。詳しくは<a href="./how-it-works">判定のしくみ</a>をご覧ください。</p><table tabindex="0"><thead><tr><th>しくみ</th><th>内容</th></tr></thead><tbody><tr><td><strong>テキストフィルター</strong></td><td>中国語のテキストと中国系Webサイトへのリンクを非表示にします</td></tr><tr><td><strong>名称フィルター</strong></td><td>中国系の企業や製品の名前が出てくる項目を非表示にします（初期設定ではオフ）</td></tr><tr><td><strong>Webサイト別スクリプト</strong></td><td>テキストだけではわからない出品者や開発元などをWebサイトごとに調べて非表示にします</td></tr><tr><td><strong>ドメインブロック</strong></td><td>中国系Webサイトを読み込む前にブロックします</td></tr></tbody></table><h2 id="ポップアップ" tabindex="-1">ポップアップ <a class="header-anchor" href="#ポップアップ" aria-label="Permalink to “ポップアップ”">​</a></h2><img src="/images/popup-ja.png" alt="cBlockのポップアップ" width="320"><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td><strong>Webサイト名</strong></td><td>現在開いているタブのWebサイト</td></tr><tr><td><strong>オン/オフのスイッチ</strong></td><td>このWebサイトでcBlockのオン/オフを切り替えます。Shiftキーを押しながらクリックすると、すべてのWebサイトでオン/オフを切り替えます</td></tr><tr><td><strong>状態</strong></td><td>cBlockがオンかオフか、またはこのページで利用できないことを表示します</td></tr><tr><td><strong>すべてのWebサイトのデフォルト</strong></td><td>すべてのWebサイトに適用される表示方法</td></tr><tr><td><strong>Webサイトごとの表示方法</strong></td><td>このWebサイトだけに適用される表示方法。再度クリックでデフォルトに戻ります</td></tr><tr><td><strong>設定</strong></td><td>設定ページを開くボタン</td></tr></tbody></table><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to “設定”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td><strong>cBlockをオンにする</strong></td><td>すべてのWebサイトでcBlockを使うかどうかを切り替えます</td></tr><tr><td><strong>非表示にした数をツールバーアイコンに表示</strong></td><td>現在のタブで非表示にした数をツールバーのアイコンに表示します</td></tr></tbody></table><h3 id="デフォルトの表示方法" tabindex="-1">デフォルトの表示方法 <a class="header-anchor" href="#デフォルトの表示方法" aria-label="Permalink to “デフォルトの表示方法”">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>ブロックした項目の表示方法</th></tr></thead><tbody><tr><td><strong>非表示</strong></td><td>項目を表示しません</td></tr><tr><td><strong>ぼかし</strong></td><td>項目をぼかして表示します（初期設定）</td></tr><tr><td><strong>マーク</strong></td><td>項目を点線の枠で囲み、操作可能な状態のまま表示します</td></tr><tr><td><strong>空白</strong></td><td>項目を非表示にしますが、レイアウトを崩さないよう元の場所を空白のまま残します</td></tr></tbody></table><h3 id="非表示にするもの" tabindex="-1">非表示にするもの <a class="header-anchor" href="#非表示にするもの" aria-label="Permalink to “非表示にするもの”">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td><strong>中国語のテキスト</strong></td><td>中国語のテキストを含む投稿や記事などを非表示にします</td></tr><tr><td>└ <strong>繁体字の中国語を表示</strong></td><td>簡体字だけを非表示にします</td></tr><tr><td><strong>中国系の企業や製品の名前</strong></td><td>中国系の企業や製品の名前が出てくる項目を非表示にします（初期設定ではオフ）</td></tr><tr><td>└ 各ジャンル</td><td>非表示にするジャンルです</td></tr><tr><td>└ <strong>すべて切り替え</strong></td><td>すべてのジャンルのオン/オフを切り替えます</td></tr><tr><td><strong>中国系Webサイトのページをブロック</strong></td><td>中国系Webサイトを読み込む前にブロックします</td></tr><tr><td><strong>中国系Webサイトへのリンク</strong></td><td>中国系Webサイトへのリンクを非表示にします</td></tr></tbody></table><blockquote><p>中国系Webサイトとは、中国で創業した企業や中国を拠点とする企業のWebサイトと <code>.cn</code>、<code>.中国</code>、または <code>.中國</code> ドメインのWebサイトです。</p></blockquote><h3 id="webサイトへの問い合わせ" tabindex="-1">Webサイトへの問い合わせ <a class="header-anchor" href="#webサイトへの問い合わせ" aria-label="Permalink to “Webサイトへの問い合わせ”">​</a></h3><ul><li>初期設定ではすべてオフです。</li><li>オンにすると、出品者、開発元、投稿者などについて表示中のWebサイトに問い合わせ、中国を拠点としているかどうかをより正確に判定します。</li><li>詳細は<a href="./privacy-policy#webサイトへの問い合わせ">プライバシーポリシー</a>をご覧ください。</li><li>Xとpixivは非公開のAPIを使用するため、アカウントが制限される場合があります。自己責任でご利用ください。</li></ul><table tabindex="0"><thead><tr><th>Webサイト</th><th>問い合わせる内容</th><th>非表示にするもの</th></tr></thead><tbody><tr><td><strong>Amazon</strong></td><td>出品者の住所、電話番号、および名前</td><td>中国を拠点とする出品者の商品</td></tr><tr><td><strong>Steam</strong></td><td>ゲームの開発元とパブリッシャー</td><td>中国を拠点とするスタジオのゲーム</td></tr><tr><td><strong>X</strong></td><td>投稿者のアカウントの所在地と接続元</td><td>中国を拠点とするアカウントのポスト</td></tr><tr><td><strong>pixiv</strong></td><td>作者のプロフィール</td><td>中国を拠点とする作者の作品</td></tr></tbody></table><h3 id="webサイトごとの表示方法" tabindex="-1">Webサイトごとの表示方法 <a class="header-anchor" href="#webサイトごとの表示方法" aria-label="Permalink to “Webサイトごとの表示方法”">​</a></h3><ul><li>Webサイトごとに表示方法を決められます。1行に1つずつWebサイトと表示方法を入力します。</li><li>表示方法を次の4つのいずれかに設定します。 <ul><li><code>hide</code>（非表示）</li><li><code>blur</code>（ぼかし）</li><li><code>mark</code>（マーク）</li><li><code>empty</code>（空白）</li></ul></li><li>一覧にないWebサイトはデフォルトの表示方法を使います。</li></ul><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>youtube.com hide</span></span>
<span class="line"><span>news.yahoo.co.jp blur</span></span>
<span class="line"><span>news.example.com mark</span></span></code></pre></div><blockquote><p>一覧のWebサイトでは親ドメインでcBlockをオフにしていてもcBlockが動作します。下位ドメインの指定が優先されるので、上の入力例では後述の<a href="#オフにするwebサイト">オフにするWebサイト</a>に <code>example.com</code> があっても、<code>news.example.com</code> では <code>mark</code> で動作します。</p></blockquote><h3 id="オフにするwebサイト" tabindex="-1">オフにするWebサイト <a class="header-anchor" href="#オフにするwebサイト" aria-label="Permalink to “オフにするWebサイト”">​</a></h3><p>cBlockを使わないWebサイトを1行に1つずつ入力します。下の入力例では <code>www.example.com</code> でもオフになります。</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>example.com</span></span></code></pre></div>`,29)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};